    TabItem EveningTab()
    {
        var source=Paper.Choice(new[]{"В планах","Топ Shikimori","Моя очередь"},0,230);var mood=Paper.Choice(EveningChoice.Moods,0,180);var genre=Paper.Choice(new[]{"Все жанры"},0,160);var format=Paper.Choice(new[]{"Любой формат","Фильм целиком","Короткий сериал ≤13","Сериал"},0,170);var time=Paper.Choice(new[]{"Без ограничения","15 минут","30 минут","1 час","2 часа","3 часа"},0,155);int[] budgets={0,15,30,60,120,180};
        var info=Paper.Text("",12,Paper.Muted);var output=new StackPanel();var top=new List<CatalogEntry>();var links=new Dictionary<int,List<CatalogEntry>>();var skipped=new HashSet<string>();bool busy=false,loaded=false,changing=false;var random=new Random();var tab=Tab("На вечер",new Border());
        string Key(Anime a)=>a.MalId>0?"mal:"+a.MalId:a.CatalogId>0?"catalog:"+a.CatalogId:a.Id;
        void Genres(){var selected=genre.SelectedItem as string;var values=source.SelectedIndex==1?top.SelectMany(e=>e.Genres.Split('|')):(source.SelectedIndex==2?(IEnumerable<Anime>)store.Choices.Active(store.Library):store.Library.Items.Where(a=>a.Status=="planned")).SelectMany(LibraryView.Genres);var items=new[]{"Все жанры"}.Concat(values.Where(s=>s.Length>0).Distinct().OrderBy(s=>s)).ToArray();changing=true;genre.ItemsSource=items;genre.SelectedIndex=Math.Max(0,Array.IndexOf(items,selected));changing=false;}
        Action Render=null!;
