            int budget=budgets[Math.Max(0,time.SelectedIndex)];if(budget>0&&meta!=null&&meta.Duration>0&&meta.Kind!="movie"){int count=budget/meta.Duration;if(meta.Episodes>0)count=Math.Min(count,meta.Episodes-anime.Watched);if(meta.AiringStatus=="ongoing")count=Math.Min(count,Math.Max(0,meta.EpisodesAired-anime.Watched));text.Children.Add(Paper.Text("Серий за это время: "+count,12,Paper.Muted));}
            var actions=new WrapPanel{Margin=new Thickness(0,8,0,0)};void Add(Button button){button.Margin=new Thickness(0,0,7,7);actions.Children.Add(button);}if(!owned)Add(Paper.Primary(Paper.AsyncButton("＋ В планы",()=>Act(()=>store.Add(meta!)))));else{Add(Paper.Primary(Paper.AsyncButton(anime.Status=="watching"?"Продолжить":"Начать смотреть",async()=>{await Act(()=>store.Status(anime,"watching"));await Edit(anime);})));Add(Paper.AsyncButton("Карточка",()=>Edit(anime)));}
            Add(Paper.Quiet(Paper.Button("Другой вариант",()=>{skipped.Add(Key(anime));Render();})));text.Children.Add(actions);
            var queue=Paper.Quiet(Paper.AsyncButton(owned&&store.Choices.Queue.Contains(anime.Id)?"Уже в очереди":"＋ В очередь",()=>Act(()=>{var item=owned?anime:store.Add(meta!);store.ChangeChoices(next=>next.Add(item));})));queue.IsEnabled=!(owned&&store.Choices.Queue.Contains(anime.Id))&&!store.ChoicesBlocked;
