        };
        async Task Load(){if(busy)return;busy=true;source.IsEnabled=false;try{if(source.SelectedIndex==1){var fresh=new List<CatalogEntry>();for(int page=1;page<=4;page++){info.Text="Загрузка топа: "+page+" / 4";var entries=await Catalog.Top(page,lifetime.Token);fresh.AddRange(entries);if(entries.Count<50)break;}var verified=await EveningPrerequisites.Load(fresh,store.Library,lifetime.Token,count=>info.Text="Проверяю предыдущие сезоны: "+count);top=fresh;links=verified;loaded=true;info.Text="Первые "+top.Count+" позиций · просмотренные и продолжения без завершённых сезонов исключены";}else{info.Text="Уточняю длительность и формат…";await store.RefreshMetadata((source.SelectedIndex==2?store.Choices.Active(store.Library):store.Library.Items.Where(a=>a.Status=="planned")).Select(a=>a.CatalogId),lifetime.Token);info.Text="Данные обновлены.";}Genres();}catch(OperationCanceledException){}catch(Exception e){info.Text="Источник недоступен. Сохранённые данные остаются доступны. "+e.Message;}finally{busy=false;source.IsEnabled=true;Render();}}
        var filters=new Grid{ColumnDefinitions=new ColumnDefinitions("*,*,*,*"),ColumnSpacing=8};var inputs=new Control[]{Paper.Field("Настроение",mood),Paper.Field("Жанр",genre),Paper.Field("Формат",format),Paper.Field("Свободное время",time)};for(int i=0;i<inputs.Length;i++){Grid.SetColumn(inputs[i],i);filters.Children.Add(inputs[i]);}
