        foreach(var choice in new[]{mood,genre,format,time})choice.SelectionChanged+=(_,_)=>{if(changing)return;skipped.Clear();Render();};source.SelectionChanged+=async(_,_)=>{skipped.Clear();Genres();Render();if(source.SelectedIndex!=1||!loaded)await Load();};tabs.SelectionChanged+=async(_,_)=>{if(ReferenceEquals(tabs.SelectedItem,tab)){Genres();Render();if(source.SelectedIndex!=1||!loaded)await Load();}};store.Changed+=()=>{Genres();Render();};return tab;
    }
    async Task HiddenDialog()
    {
        var rows=new StackPanel{Spacing=10};var panel=Paper.Stack(Paper.Text("Не предлагать на вечер",25),Paper.Text("Тайтлы остаются в библиотеке и очереди. Верните их, чтобы снова участвовать в подборе.",12,Paper.Muted),rows);var dialog=Paper.Dialog(this,"Скрытые аниме",Paper.Scroll(panel),620,470);Action render=null!;
        render=()=>{rows.Children.Clear();if(store.Choices.Hidden.Count==0)rows.Children.Add(Paper.Text("Скрытых аниме нет.",16));foreach(var entry in store.Choices.Hidden.OrderBy(a=>a.Title)){var row=new DockPanel();var restore=Paper.AsyncButton("Вернуть",async()=>{store.ChangeChoices(next=>next.Hidden.RemoveAll(a=>a.LibraryId==entry.LibraryId&&a.CatalogId==entry.CatalogId&&a.MalId==entry.MalId));render();await Task.CompletedTask;});DockPanel.SetDock(restore,Dock.Right);row.Children.Add(restore);row.Children.Add(Paper.Text(entry.Title,16));rows.Children.Add(row);}};render();await Modal(dialog);
    }
